  .toc a:hover { border-bottom-color: var(--accent); }

  .toc .section-num {
    display: inline-block;
    width: 24px;
    color: var(--muted);
    font-weight: 600;
    font-size: 0.8rem;
  }

  /* Section */
  .section {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 36px 40px;
    margin-bottom: 32px;
  }

  .section h2 {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 8px;
    color: var(--text);
    letter-spacing: -0.01em;
