    border-left: 4px solid #3b82f6;
    border-radius: 0 8px 8px 0;
    padding: 16px 20px;
    margin-bottom: 14px;
  }

  .takeaway .takeaway-title {
    font-weight: 700;
    font-size: 0.95rem;
    color: #1e40af;
    margin-bottom: 4px;
  }

  .takeaway p {
