  /* Tables */
  .data-table {
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0 24px;
    font-size: 0.88rem;
  }

  .data-table thead th {
    background: #f1f5f9;
    color: #475569;
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 0.06em;
    padding: 12px 14px;
    text-align: left;
    border-bottom: 2px solid var(--border);
  }

  .data-table tbody td {
    padding: 11px 14px;
    border-bottom: 1px solid #f1f5f9;
    vertical-align: middle;
  }

  .data-table tbody tr:hover { background: #f8fafc; }

  .data-table .num { text-align: right; font-variant-numeric: tabular-nums; }

  .data-table .app-name {
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .app-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    display: inline-block;
    flex-shrink: 0;
  }

  .dot-chatgpt { background: var(--chatgpt); }
  .dot-copilot { background: var(--copilot); }
  .dot-gemini { background: var(--gemini); }
  .dot-perplexity { background: var(--perplexity); }
  .dot-claude { background: var(--claude); }

  /* Badges */
  .badge {
    display: inline-block;
    padding: 2px 10px;
    border-radius: 999px;
    font-size: 0.75rem;
    font-weight: 600;
  }

  .badge-green { background: #dcfce7; color: #166534; }
  .badge-yellow { background: #fef3c7; color: #92400e; }
  .badge-red { background: #fce4ec; color: #b71c1c; }
  .badge-blue { background: #dbeafe; color: #1e40af; }
  .badge-gray { background: #f1f5f9; color: #475569; }

  /* Charts */
  .chart-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin: 20px 0;
  }

  .chart-box {
    background: #fafbfc;
    border: 1px solid #e8ecf1;
    border-radius: 10px;
    padding: 20px;
  }

  .chart-box h4 {
    margin: 0 0 12px;
    font-size: 0.88rem;
    color: var(--muted);
  }

  .chart-box canvas {
    max-height: 320px;
  }

  .chart-full {
    grid-column: 1 / -1;
  }

  /* Bar visual in table */
  .bar-cell {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .bar-fill {
    height: 8px;
    border-radius: 4px;
    min-width: 2px;
    transition: width 0.3s;
  }

  .bar-label {
    font-size: 0.82rem;
    color: var(--muted);
    white-space: nowrap;
  }

  /* Recommendation cards */
  .rec-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
    gap: 20px;
    margin-top: 20px;
  }

  .rec-card {
    border: 1px solid var(--border);
    border-radius: 10px;
